tool_input.command:
node --input-type=module -e "
import {readFileSync} from 'node:fs'
import {extractTags} from './project-graph/extract.mjs'
const {locations, errors} = extractTags('.')
const cited = new Set(locations.flatMap(l => l.claims))
const defined = [...readFileSync('project-graph/claims.ttl','utf8').matchAll(/^claim:([a-z0-9-]+) a model:/gm)].map(m => m[1])
console.log('locations', locations.length, 'errors', errors.length, 'defined', defined.length, 'cited', cited.size)
console.log('uncited:', defined.filter(d => !cited.has(d)).join(' '))
console.log('undefined:', [...cited].filter(c => !defined.includes(c)).join(' '))
"
